pub fn ihc_census_of_graph(
    g: Rc<ResolvedGraph>,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
    sources: Rc<Vec<Rc<SourceFile>>>,
    subjects: Rc<Vec<String>>,
) -> Rc<IhcCensus> {
    {
        let subject_set = subjects.iter().cloned().fold(
            v1_rt::rc_empty_map::<String, bool>(),
            |acc: Rc<HashMap<String, bool>>, p: String| v1_rt::rc_map_insert(acc, p.clone(), true),
        );
        let templates = Rc::new({
            let mut __result = Vec::new();
            for t in Rc::new({
                let mut __result = Vec::new();
                for m in g.modules.clone().iter().cloned() {
                    __result.extend(
                        (*ihc_module_templates(m.clone(), si.clone()))
                            .iter()
                            .cloned(),
                    );
                }
                __result
            })
            .iter()
            .cloned()
            {
                if ihc_in(subject_set.clone(), t.file.clone()) {
                    __result.push(t);
                }
            }
            __result
        });
        Rc::new(IhcCensus {
            templates: templates.clone(),
            rows: ihc_number_holes(Rc::new({
                let mut __result = Vec::new();
                for t in templates.iter().cloned() {
                    __result.extend((*t.holes.clone()).iter().cloned());
                }
                __result
            })),
            lexical: Rc::new({
                let mut __result = Vec::new();
                for s in Rc::new({
                    let mut __result = Vec::new();
                    for s in sources.iter().cloned() {
                        if ihc_in(subject_set.clone(), s.path.clone()) {
                            __result.push(s);
                        }
                    }
                    __result
                })
                .iter()
                .cloned()
                {
                    __result.push(ihc_lexical_count(s.clone()));
                }
                __result
            }),
        })
    }
}

